% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).


v(iso_char_code_2_01, true(Code == 0'a), (char_code(a, Code))).
v(iso_char_code_2_02, true(Char == Atom), (char_code(Char, 99), atom_codes(Atom, [99]))).
v(iso_char_code_2_03, true(Char == c), (char_code(Char, 0'c))).
v(iso_char_code_2_05, true, (char_code(b, 0'b))).
v(iso_char_code_2_06, error(type_error(character,'ab')), (char_code('ab', _Code))).
v(iso_char_code_2_07, error(instantiation_error), (char_code(_Char, _Code))).
v(eddbali_char_code_2_08, error(type_error(integer,x)), (char_code(a, x))).
v(eddbali_char_code_2_09, error(representation_error(character_code)), (char_code(_Char, -2))).
v(lgt_char_code_2_11, error(type_error(character,42)), (char_code(42, _Code))).
